// Some portions generated by Claude
import test from 'node:test';
import assert from 'node:assert/strict';
import {computeGraphLayout} from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import {computeSparseLayout} from '../../../main/frontend/graph-explorer/graph-layout-sparse.ts';
import {separateLayoutRectangles} from '../../../main/frontend/graph-explorer/graph-layout-overlap.ts';
import {graphNodeSize} from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import {SpatialGrid} from '../../../main/frontend/graph-explorer/spatial-grid.ts';
import {sharedHubNetwork} from './fixtures/layout-networks.mjs';
import {groupedNetwork} from './fixtures/layout-adversarial.mjs';
import {createLargeStressGraph, createStarStressGraph} from '../../../main/frontend/graph-explorer/graph-fixtures.ts';
import {intersectingGroupBoxes} from './fixtures/layout-measurements.mjs';

function assertClearance(graph, positions) {
  const index = new SpatialGrid(256), found = [];
  for (const node of graph.nodes) {
    const p = positions.get(node.id), size = graphNodeSize(node);
    // Clearance is between visible card edges, not a larger card or zoom change.
    const b = {minX: p.x - (size.width + 48) / 2, maxX: p.x + (size.width + 48) / 2,
      minY: p.y - (size.height + 36) / 2, maxY: p.y + (size.height + 36) / 2};
    assert.equal(index.search(b.minX + .02, b.minY + .02, b.maxX - .02, b.maxY - .02, found).length, 0,
      `node ${node.id} must have 48px horizontal or 36px vertical clearance`);
    index.insert(b);
  }
}

for (const axis of ['x', 'y']) test(`repair opens ${axis === 'x' ? 'horizontal' : 'vertical'} space without moving pins`, () => {
  const nodes = ['a', 'b'].map(id => ({id, label: 'Readable node', kind: 'iri', x: 0, y: 0, pinned: id === 'a'}));
  const size = graphNodeSize(nodes[0]);
  nodes[1][axis] = axis === 'x' ? size.width + 32 : size.height + 24;
  const graph = {nodes, edges: [], revision: 1}, before = structuredClone(graph);
  const positions = new Map(nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  separateLayoutRectangles(graph, positions, {repairOnly: true});
  assertClearance(graph, positions);
  assert.deepEqual(positions.get('a'), {x: 0, y: 0});
  assert.deepEqual(graph, before);
  const settled = new Map(positions);
  separateLayoutRectangles(graph, positions, {repairOnly: true});
  assert.deepEqual(positions, settled, 'repeated repair must not keep expanding the graph');
});

test('ordinary and hub layouts leave room between visible cards', async () => {
  for (const graph of [sharedHubNetwork(), createStarStressGraph(80, 1)]) {
    const before = structuredClone(graph), result = await computeGraphLayout(graph);
    assertClearance(graph, result.positions);
    assert.deepEqual(graph, before);
  }
});

test('roomier named groups stay separate and retain their pinned anchor', async () => {
  const {graph, groups} = groupedNetwork(3, 10);
  graph.nodes[0].pinned = true; graph.nodes[0].x = -600; graph.nodes[0].y = -400;
  const result = await computeGraphLayout(graph, {groups});
  assertClearance(graph, result.positions);
  assert.equal(intersectingGroupBoxes(graph, result.positions, groups), 0);
  assert.deepEqual(result.positions.get('0'), {x: -600, y: -400});
});

test('large-graph packing and sparse fallback use the same roomier clearance', async () => {
  const graph = createLargeStressGraph(1601, 1);
  assertClearance(graph, (await computeGraphLayout(graph)).positions);
  assertClearance(graph, computeSparseLayout(graph).positions);
});

test('hierarchy leaves extra space within and between ranks', async () => {
  const nodes = ['root', 'left', 'right'].map(id => ({id, label: 'Readable node', kind: 'iri'}));
  const graph = {nodes, revision: 1, edges: ['left', 'right'].map(target => ({id: target, source: 'root', target,
    label: 'contains', predicate: 'urn:contains'}))};
  const {positions} = await computeGraphLayout(graph, {mode: 'hierarchy'});
  assertClearance(graph, positions);
  const root = positions.get('root');
  for (const child of nodes.slice(1)) assert.ok(positions.get(child.id).y - root.y - graphNodeSize(child).height >= 90 - .02);
});
